    # Include bounds around each contiguous partition.
    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))
    # Find a partition containing non-background, non-divider marks.
    source = None
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            marks = [[g[r][c] for c in range(c0, c1)] for r in range(r0, r1)]
            if any(v not in (bg, 4) for row in marks for v in row):
                source = marks
                break
        if source is not None:
            break
    if source is None:
        return g
    for r0, r1 in row_ranges:
